import unittest

from solucao import alinhar
from solucao import preencher


class TestAlinharEPreencher(unittest.TestCase):
    def test_completa_com_espacos(self):
        """alinhar poe espacos a direita ate a largura"""
        self.assertEqual(alinhar("ola", 5), "ola  ")

    def test_um_espaco_so(self):
        """alinhar poe um espaco quando falta uma posicao"""
        self.assertEqual(alinhar("oi", 3), "oi ")

    def test_ja_cabe_nao_muda(self):
        """alinhar devolve o texto como esta quando ele ja cabe"""
        self.assertEqual(alinhar("banana", 3), "banana")

    def test_completa_com_zeros(self):
        """preencher poe zeros a esquerda ate a largura"""
        self.assertEqual(preencher("12", 4), "0012")

    def test_um_zero_so(self):
        """preencher poe um zero quando falta uma posicao"""
        self.assertEqual(preencher("7", 3), "007")

    def test_ja_cabe_nao_poe_zero(self):
        """preencher devolve o texto como esta quando ele ja cabe"""
        self.assertEqual(preencher("12345", 3), "12345")

